# Purpose: Switch-CaseSensitive — General-purpose PowerShell utilities.
$words = "MicrosOFT","MicroSoft","Microsoft","MiCroSoFt","MICROsoft"$matched=0switch ($words){ "Microsoft" { write-host "'$_' matched!";$matched++} default     { write-host "do some default action"}}write-output "Switch with (default) no case sensitivity."write-host "$matched matches."$matched=0switch -CaseSensitive ($words){ "Microsoft" { write-host "'$_' matched!";$matched++} default     { write-host "call some default action"}}write-output "Switch with case sensitivity."write-host "$matched matches."